function minPlanEffort(effort: number[], days: number): number {
  const n = effort.length;
  if (n < days) return -1;
  const go = (i: number, d: number): number => {
    if (d === 1) return Math.max(...effort.slice(i));
    let best = Infinity, top = 0;
    for (let j = i; j <= n - d; j++) {
      top = Math.max(top, effort[j]);
      best = Math.min(best, top + go(j + 1, d - 1));
    }
    return best;
  };
  return go(0, days);
}

