function minPlanEffort(effort: number[], days: number): number {
  const n = effort.length;
  if (n < days) return -1;
  const dp: number[][] = Array.from({ length: days + 1 }, () => new Array(n + 1).fill(Infinity));
  dp[0][0] = 0;
  for (let k = 1; k <= days; k++) {
    for (let i = k; i <= n; i++) {
      let top = 0;
      for (let j = i - 1; j >= k - 1; j--) {
        top = Math.max(top, effort[j]);
        dp[k][i] = Math.min(dp[k][i], dp[k - 1][j] + top);
      }
    }
  }
  return dp[days][n];
}

