class Solution:
    def minPlanEffort(self, effort: List[int], days: int) -> int:
        n = len(effort)
        if n < days:
            return -1
        INF = math.inf
        prev = [0] + [INF] * n
        for k in range(1, days + 1):
            cur = [INF] * (n + 1)
            for i in range(k, n + 1):
                top, best = 0, INF
                for j in range(i - 1, k - 2, -1):
                    if effort[j] > top:
                        top = effort[j]
                    v = prev[j] + top
                    if v < best:
                        best = v
                cur[i] = best
            prev = cur
        return prev[n]

